{"draft":{"version":"a0","html":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sticker Table</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background: #f4ecd8;
    overflow: hidden;
    font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  }
  #wrap {
    position: fixed;
    inset: 0;
    width: 100vw;
    height: 100dvh;
  }
  canvas {
    display: block;
    width: 100%;
    height: 100%;
    touch-action: none;
  }
  #clearBtn {
    position: fixed;
    right: 14px;
    bottom: 14px;
    min-width: 90px;
    min-height: 48px;
    background: #3d405b;
    color: #f4ecd8;
    border: none;
    border-radius: 14px;
    font-size: 17px;
    font-weight: 700;
    font-family: inherit;
    box-shadow: 0 3px 6px rgba(61,64,91,0.5);
    z-index: 10;
  }
  #clearBtn:active {
    transform: translateY(1px);
  }
</style>
</head>
<body>
<div id="wrap">
  <canvas id="game"></canvas>
</div>
<button id="clearBtn">Clear</button>
<script>
  const CARTRIDGE = {
    send(type, payload = {}) {
      window.parent.postMessage(
        { source: "cartridge", v: 1, type, payload },
        "*",
      );
    },
  };
</script>
<script>
(function() {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const clearBtn = document.getElementById("clearBtn");

  let dpr = Math.max(1, window.devicePixelRatio || 1);
  let W = 0, H = 0;

  function resize() {
    W = window.innerWidth;
    H = window.innerHeight;
    dpr = Math.max(1, window.devicePixelRatio || 1);
    canvas.width = Math.floor(W * dpr);
    canvas.height = Math.floor(H * dpr);
    canvas.style.width = W + "px";
    canvas.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    draw();
  }
  window.addEventListener("resize", resize);

  // ---- palette ----
  const COL_BG = "#f4ecd8";
  const COL_LAYER = "#e07a5f";
  const COL_ACCENT = "#3d405b";
  const COL_HILITE = "#81b29a";

  // seeded jitter helper
  function mulberry32(seed) {
    return function() {
      seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  const STICKER_TYPES = ["leaf", "shell", "star"];

  const pieces = [];
  let tally = 0;
  let paused = false;
  let running = false;
  let nextTypeIndex = 0;
  let seedCounter = 1;

  let t = 0; // animation time

  function place(x, y) {
    const type = STICKER_TYPES[nextTypeIndex % STICKER_TYPES.length];
    nextTypeIndex++;
    const rnd = mulberry32(seedCounter++ * 7919 + Math.floor(x * 13 + y * 7));
    const scale = 0.85 + rnd() * 0.4;
    const rot = (rnd() - 0.5) * 0.6;
    const hue = rnd();
    const wobblePhase = rnd() * Math.PI * 2;
    const wobbleSpeed = 1.2 + rnd() * 0.8;
    pieces.push({
      x, y, type, scale, rot, hue,
      wobblePhase, wobbleSpeed,
      born: t
    });
    tally += 1;
    CARTRIDGE.send("score", { value: tally });
  }

  function clearTable() {
    pieces.length = 0;
    tally = 0;
    nextTypeIndex = 0;
    CARTRIDGE.send("score", { value: 0 });
    draw();
  }

  function jitterPoint(rnd, x, y, amt) {
    return [x + (rnd() - 0.5) * amt, y + (rnd() - 0.5) * amt];
  }

  function drawShadowPath(pathFn) {
    ctx.save();
    ctx.shadowColor = "rgba(61,64,91,0.35)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetX = 2;
    ctx.shadowOffsetY = 3;
    pathFn();
    ctx.restore();
  }

  function drawLeaf(rnd, size, colorMain) {
    // leaf shape: pointed oval with a vein
    const pts = [];
    const n = 10;
    for (let i = 0; i <= n; i++) {
      const a = (i / n) * Math.PI * 2;
      const rx = size * (0.55 + 0.45 * Math.abs(Math.cos(a)));
      const ry = size * 0.85;
      let px = Math.cos(a) * rx * 0.5;
      let py = Math.sin(a) * ry * 0.5;
      const [jx, jy] = jitterPoint(rnd, px, py, 1.5);
      pts.push([jx, jy]);
    }
    const build = () => {
      ctx.beginPath();
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
      ctx.closePath();
    };
    drawShadowPath(() => {
      ctx.fillStyle = colorMain;
      build();
      ctx.fill();
    });
    build();
    ctx.fillStyle = colorMain;
    ctx.fill();
    // vein
    ctx.strokeStyle = COL_ACCENT;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(0, -size * 0.4);
    ctx.lineTo(0, size * 0.4);
    ctx.stroke();
  }

  function drawShell(rnd, size, colorMain) {
    const n = 12;
    const build = () => {
      ctx.beginPath();
      for (let i = 0; i <= n; i++) {
        const a = Math.PI + (i / n) * Math.PI;
        let px = Math.cos(a) * size * 0.6;
        let py = Math.sin(a) * size * 0.55 + size * 0.15;
        const [jx, jy] = jitterPoint(rnd, px, py, 1.5);
        if (i === 0) ctx.moveTo(jx, jy); else ctx.lineTo(jx, jy);
      }
      ctx.lineTo(size * 0.05, size * 0.6);
      ctx.closePath();
    };
    drawShadowPath(() => {
      ctx.fillStyle = colorMain;
      build();
      ctx.fill();
    });
    build();
    ctx.fillStyle = colorMain;
    ctx.fill();
    // ribs
    ctx.strokeStyle = COL_ACCENT;
    ctx.lineWidth = 1.2;
    for (let i = 1; i < 5; i++) {
      const a = Math.PI + (i / 5) * Math.PI;
      ctx.beginPath();
      ctx.moveTo(0, size * 0.1);
      ctx.lineTo(Math.cos(a) * size * 0.6, Math.sin(a) * size * 0.55 + size * 0.15);
      ctx.stroke();
    }
  }

  function drawStar(rnd, size, colorMain) {
    const spikes = 5;
    const outerR = size * 0.65;
    const innerR = size * 0.28;
    const build = () => {
      ctx.beginPath();
      for (let i = 0; i < spikes * 2; i++) {
        const a = (Math.PI / spikes) * i - Math.PI / 2;
        const r = i % 2 === 0 ? outerR : innerR;
        let px = Math.cos(a) * r;
        let py = Math.sin(a) * r;
        const [jx, jy] = jitterPoint(rnd, px, py, 1.4);
        if (i === 0) ctx.moveTo(jx, jy); else ctx.lineTo(jx, jy);
      }
      ctx.closePath();
    };
    drawShadowPath(() => {
      ctx.fillStyle = colorMain;
      build();
      ctx.fill();
    });
    build();
    ctx.fillStyle = colorMain;
    ctx.fill();
  }

  function mixColor(base, amt) {
    // simple lighten/darken toward highlight or accent for variety
    return base;
  }

  function pieceColor(p) {
    if (p.hue < 0.34) return COL_LAYER;
    if (p.hue < 0.67) return COL_HILITE;
    return COL_ACCENT === "#3d405b" ? "#e07a5f" : COL_LAYER; // fallback variety
  }

  function drawPiece(p) {
    const wobble = Math.sin(t * p.wobbleSpeed + p.wobblePhase) * 0.08;
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.rot + wobble);
    ctx.scale(p.scale, p.scale);
    const rnd = mulberry32(Math.floor(p.x * 31 + p.y * 17 + 1));
    const size = 46;
    let col = COL_LAYER;
    if (p.type === "leaf") col = COL_HILITE;
    else if (p.type === "shell") col = COL_LAYER;
    else col = COL_ACCENT;
    // stars use accent as darkest tone per style rule but need visible fill; use layer-ish
    if (p.type === "star") col = "#e0a15f";
    if (p.type === "leaf") drawLeaf(rnd, size, col);
    else if (p.type === "shell") drawShell(rnd, size, col);
    else drawStar(rnd, size, col);
    ctx.restore();
  }

  function drawBackgroundCard() {
    // background base
    ctx.fillStyle = COL_BG;
    ctx.fillRect(0, 0, W, H);
    // subtle table plate
    const rnd = mulberry32(99);
    const margin = 10;
    const pts = [
      [margin, margin], [W - margin, margin],
      [W - margin, H - margin], [margin, H - margin]
    ];
    ctx.save();
    ctx.shadowColor = "rgba(61,64,91,0.25)";
    ctx.shadowBlur = 8;
    ctx.shadowOffsetY = 4;
    ctx.fillStyle = "#efe3c8";
    ctx.beginPath();
    pts.forEach((p, i) => {
      const [jx, jy] = jitterPoint(rnd, p[0], p[1], 2);
      if (i === 0) ctx.moveTo(jx, jy); else ctx.lineTo(jx, jy);
    });
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawHUD() {
    // score plate top-left
    const plateW = 150, plateH = 56;
    const x = 12, y = 12;
    ctx.save();
    ctx.shadowColor = "rgba(61,64,91,0.3)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetY = 3;
    ctx.fillStyle = COL_ACCENT;
    roundRect(x, y, plateW, plateH, 12);
    ctx.fill();
    ctx.restore();

    ctx.fillStyle = COL_BG;
    ctx.font = "bold 18px sans-serif";
    ctx.textBaseline = "middle";
    ctx.textAlign = "left";
    ctx.fillText("Stickers: " + tally, x + 14, y + plateH / 2 + 1);
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function drawHint() {
    if (running) return;
    const pulse = 0.6 + 0.4 * Math.sin(t * 3);
    ctx.save();
    ctx.globalAlpha = pulse;
    ctx.fillStyle = COL_ACCENT;
    ctx.font = "bold 26px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("Tap to begin", W / 2, H / 2);
    ctx.restore();
  }

  function draw() {
    drawBackgroundCard();
    for (const p of pieces) drawPiece(p);
    drawHUD();
    drawHint();
  }

  function frame() {
    if (!paused) {
      t += 1 / 60;
    }
    draw();
    requestAnimationFrame(frame);
  }

  function backToTitle() {
    clearTable();
    running = false;
    paused = false;
  }

  canvas.style.touchAction = "none";
  canvas.addEventListener("pointerdown", (event) => {
    event.preventDefault();
    if (paused) return;
    if (!running) {
      running = true;
      CARTRIDGE.send("start");
      return;
    }
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    place(x, y);
  });

  clearBtn.addEventListener("click", () => {
    clearTable();
  });

  window.addEventListener("message", (event) => {
    const data = event.data;
    if (!data || data.source !== "cartridge-host") return;
    if (data.type === "pause") paused = true;
    if (data.type === "resume") paused = false;
    if (data.type === "reset") backToTitle();
  });

  resize();
  CARTRIDGE.send("boot", { title: "Sticker Table", gameType: "toy-box", lang: "en" });
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
"}}

